sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float beat;
uniform float2 center;
uniform float amount;
uniform float curve;
uniform float focusRadius;
uniform float gain;
uniform float opacity;
uniform float decay;
uniform float beats;
uniform float offset;
uniform float bpm;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float e = pow(saturate(beat), curve);
    float2 ctr = center * size;
    float2 d = coord - ctr;
    float mask = smoothstep(focusRadius, focusRadius + 0.5, length(d) / (length(size) * 0.5));
    float4 acc = float4(0.0);
    for (int i = 0; i < 12; i++) {
        float s = 1.0 - amount * e * mask * (float(i) / 11.0);
        acc += tex(ctr + d * s);
    }
    acc = acc / 12.0;
    return fin(c, float4(acc.rgb * mix(1.0, gain, e), acc.a), opacity);
}
